import React, { useState, useEffect } from 'react';
import { Invoice } from './Invoice'; // Assuming you have an Invoice interface or type

const BASE_SALARY = 43000 + (43000 * 0.08); // 46440
const TAX_YEAR_START = new Date('2024-04-06'); // For 2024/2025

// Tax Bands (England 2024/2025)
const PA_THRESHOLD = 12570;
const BASIC_RATE_THRESHOLD = 50270;
const HIGHER_RATE_THRESHOLD = 125140;

const BASIC_RATE = 0.20;
const HIGHER_RATE = 0.40;
const ADDITIONAL_RATE = 0.45;

// NI Class 4 Bands (2024/2025)
const NI_LOWER_THRESHOLD = 12570;
const NI_UPPER_THRESHOLD = 50270;
const NI_LOWER_RATE = 0.06;
const NI_HIGHER_RATE = 0.02;

const calculateTaxForInvoice = (invoiceAmount: number, baseIncome: number, alreadyEarnedThisYear: number) => {
    let incomeTax = 0;
    let nationalInsurance = 0;
    const startingIncome = baseIncome + alreadyEarnedThisYear;

    // Simplified marginal tax calculation
    let taxableIncome = invoiceAmount;
    let remainingIncome = startingIncome;

    if (remainingIncome < PA_THRESHOLD) {
        // No tax on Personal Allowance
    } else {
        taxableIncome -= Math.max(0, PA_THRESHOLD - remainingIncome);
        remainingIncome = PA_THRESHOLD; // Cap at PA threshold
    }

    if (taxableIncome > 0) {
        const basicRateAmount = Math.min(taxableIncome, BASIC_RATE_THRESHOLD - remainingIncome);
        incomeTax += basicRateAmount * BASIC_RATE;
        remainingIncome += basicRateAmount;
        taxableIncome -= basicRateAmount;
    }

    if (taxableIncome > 0) {
        const higherRateAmount = Math.min(taxableIncome, HIGHER_RATE_THRESHOLD - remainingIncome);
        incomeTax += higherRateAmount * HIGHER_RATE;
        remainingIncome += higherRateAmount;
        taxableIncome -= higherRateAmount;
    }

    if (taxableIncome > 0) {
        incomeTax += taxableIncome * ADDITIONAL_RATE;
    }

    // National Insurance calculations
    const niTaxableAmount = Math.max(0, taxableIncome);
    if (niTaxableAmount > 0 && startingIncome < NI_UPPER_THRESHOLD) {
        if (startingIncome < NI_LOWER_THRESHOLD) {
            nationalInsurance += Math.max(0, Math.min(niTaxableAmount, NI_UPPER_THRESHOLD - startingIncome) * NI_LOWER_RATE);
        } else {
            nationalInsurance += Math.max(0, Math.min(niTaxableAmount, NI_UPPER_THRESHOLD - startingIncome) * NI_LOWER_RATE);
            nationalInsurance += Math.max(0, (niTaxableAmount - NI_UPPER_THRESHOLD) * NI_HIGHER_RATE);
        }
    }

    return { incomeTax, nationalInsurance, totalTax: incomeTax + nationalInsurance };
};

